import bannerImg from "../assets/image.png";
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Swal from "sweetalert2";

// ── Datos simulados ────────────────────────────────────────────────
const DETECCIONES = [
  { id: 1, fecha: "24/07/2025", hora: "09:15 a.m.", lote: "Lote 7", bloque: "Bloque B", resultado: "Sigatoka Negra", severidad: "Moderado", image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100" },
  { id: 2, fecha: "24/07/2025", hora: "08:45 a.m.", lote: "Lote 6", bloque: "Bloque A", resultado: "Sigatoka Negra", severidad: "Severo",   image: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6?q=80&w=100" },
  { id: 3, fecha: "23/07/2025", hora: "04:30 p.m.", lote: "Lote 5", bloque: "Bloque D", resultado: "Sana",           severidad: "Leve",     image: "https://images.unsplash.com/photo-1471193945509-9ad0617afabf?q=80&w=100" },
  { id: 4, fecha: "23/07/2025", hora: "11:20 a.m.", lote: "Lote 4", bloque: "Bloque B", resultado: "Sigatoka Negra", severidad: "Moderado", image: "https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?q=80&w=100" },
  { id: 5, fecha: "22/07/2025", hora: "03:10 p.m.", lote: "Lote 3", bloque: "Bloque C", resultado: "Sana",           severidad: "Leve",     image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100" },
];

const LOTES = [
  { nombre: "Lote 7 - Bloque B", cantidad: 28, max: 28 },
  { nombre: "Lote 6 - Bloque A", cantidad: 24, max: 28 },
  { nombre: "Lote 5 - Bloque D", cantidad: 20, max: 28 },
  { nombre: "Lote 4 - Bloque B", cantidad: 18, max: 28 },
  { nombre: "Lote 3 - Bloque C", cantidad: 16, max: 28 },
];

const EVOLUCION = [
  { dia: "18 Jul", val: 22 },
  { dia: "19 Jul", val: 38 },
  { dia: "20 Jul", val: 45 },
  { dia: "21 Jul", val: 30 },
  { dia: "22 Jul", val: 52 },
  { dia: "23 Jul", val: 48 },
  { dia: "24 Jul", val: 68 },
];

const severidadConfig = {
  Moderado: { bg: "bg-orange-100", text: "text-orange-600", border: "border-orange-200" },
  Severo:   { bg: "bg-red-100",    text: "text-red-600",    border: "border-red-200"    },
  Leve:     { bg: "bg-green-100",  text: "text-green-700",  border: "border-green-200"  },
};

const resultadoColor = {
  "Sigatoka Negra": "text-red-500",
  "Sana":           "text-green-600",
};

// ── Componente principal ───────────────────────────────────────────
export default function HomePage() {
  const navigate   = useNavigate();
  const { user, handleLogout } = useAuth();
  const [activePage, setActivePage] = useState("deteccion");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [detections, setDetections] = useState([]);
  const canvasRef = useRef(null);

  const firstName = user?.displayName
    ? user.displayName.split(" ")[0]
    : user?.email ? user.email.split("@")[0] : "Usuario";

  const fullName = user?.displayName || user?.email?.split("@")[0] || "Usuario";

  const initials = fullName.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2);

  const storageKey = `scans_${user?.uid || user?.email || "guest"}`;

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem(storageKey) || "[]");
    setDetections(saved);
  }, [user]);

  useEffect(() => {
    dibujarGrafica();
  }, []);

  const dibujarGrafica = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;
    const pad = { top: 16, right: 16, bottom: 32, left: 36 };
    const vals = EVOLUCION.map(e => e.val);
    const maxVal = Math.max(...vals);
    const minVal = 0;

    ctx.clearRect(0, 0, W, H);

    // Grid lines
    for (let i = 0; i <= 4; i++) {
      const y = pad.top + ((H - pad.top - pad.bottom) / 4) * i;
      ctx.strokeStyle = "#e5e7eb";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad.left, y);
      ctx.lineTo(W - pad.right, y);
      ctx.stroke();
      const label = Math.round(maxVal - (maxVal / 4) * i);
      ctx.fillStyle = "#9ca3af";
      ctx.font = "10px Inter, sans-serif";
      ctx.fillText(label, 2, y + 4);
    }

    const pts = EVOLUCION.map((e, i) => ({
      x: pad.left + (i / (EVOLUCION.length - 1)) * (W - pad.left - pad.right),
      y: pad.top + (1 - (e.val - minVal) / (maxVal - minVal)) * (H - pad.top - pad.bottom),
    }));

    // Área bajo la curva
    const grad = ctx.createLinearGradient(0, pad.top, 0, H - pad.bottom);
    grad.addColorStop(0, "rgba(34,107,34,0.15)");
    grad.addColorStop(1, "rgba(34,107,34,0)");
    ctx.beginPath();
    ctx.moveTo(pts[0].x, H - pad.bottom);
    pts.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.lineTo(pts[pts.length - 1].x, H - pad.bottom);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // Línea
    ctx.beginPath();
    ctx.strokeStyle = "#1f5e1f";
    ctx.lineWidth = 2.5;
    ctx.lineJoin = "round";
    pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.stroke();

    // Puntos
    pts.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
      ctx.fillStyle = "#1f5e1f";
      ctx.fill();
      ctx.strokeStyle = "white";
      ctx.lineWidth = 2;
      ctx.stroke();
    });

    // Labels días
    EVOLUCION.forEach((e, i) => {
      const x = pad.left + (i / (EVOLUCION.length - 1)) * (W - pad.left - pad.right);
      ctx.fillStyle = "#6b7280";
      ctx.font = "10px Inter, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(e.dia, x, H - 4);
    });
  };

  const confirmLogout = () => {
    Swal.fire({
      title: "¿Cerrar sesión?",
      text: "Tendrás que iniciar sesión de nuevo.",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#1f5e1f",
      cancelButtonColor: "#9ca3af",
      confirmButtonText: "Sí, cerrar sesión",
      cancelButtonText: "Cancelar",
      background: "#f5f2ec",
      customClass: { popup: "rounded-3xl" },
    }).then(result => {
      if (result.isConfirmed) {
        handleLogout();
        navigate("/login");
      }
    });
  };

  const navItems = [
    { key: "dashboard",  label: "Dashboard",                  icon: "🏠" },
    { key: "usuarios",   label: "Usuarios",                   icon: "👥" },
    { key: "deteccion",  label: "Detección de Enfermedades",  icon: "🔬" },
    { key: "seguimiento",label: "Recomendación y Seguimiento",icon: "🌿" },
    { key: "geolocal",   label: "Geolocalización y Registro", icon: "📍" },
    { key: "informes",   label: "Visualización e Informes",   icon: "📊" },
  ];

  const handleNav = (key) => {
    setActivePage(key);
    setSidebarOpen(false);
    if (key === "geolocal") navigate("/map");
  };

  const totalScans     = detections.length || 128;
  const sigatokaNegra  = detections.filter(d => d.enfermedad === "Sigatoka Negra").length || 68;
  const moderadoSevero = detections.filter(d => ["Alto", "Medio"].includes(d.nivel_riesgo)).length || 42;
  const estaSemana     = 24;

  // Donut chart con canvas
  const DonutChart = () => {
    const ref = useRef(null);
    useEffect(() => {
      const canvas = ref.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      const W = canvas.width, H = canvas.height;
      const cx = W / 2, cy = H / 2, r = Math.min(W, H) / 2 - 12;

      const datos = [
        { val: 44, color: "#22c55e" },
        { val: 42, color: "#f97316" },
        { val: 24, color: "#ef4444" },
        { val: 18, color: "#14532d" },
      ];
      const total = datos.reduce((a, b) => a + b.val, 0);
      let startAngle = -Math.PI / 2;

      ctx.clearRect(0, 0, W, H);
      datos.forEach(d => {
        const slice = (d.val / total) * Math.PI * 2;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.arc(cx, cy, r, startAngle, startAngle + slice);
        ctx.closePath();
        ctx.fillStyle = d.color;
        ctx.fill();
        startAngle += slice;
      });

      // Hueco central
      ctx.beginPath();
      ctx.arc(cx, cy, r * 0.55, 0, Math.PI * 2);
      ctx.fillStyle = "white";
      ctx.fill();

      // Texto central
      ctx.fillStyle = "#1f2937";
      ctx.font = "bold 18px Inter, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("128", cx, cy - 4);
      ctx.fillStyle = "#6b7280";
      ctx.font = "10px Inter, sans-serif";
      ctx.fillText("Total", cx, cy + 12);
    }, []);
    return <canvas ref={ref} width={140} height={140} />;
  };

  return (
    <div className="min-h-screen bg-[#f8faf8] flex flex-col">

      {/* ── TOPBAR ── */}
      <header className="bg-white border-b border-gray-100 px-6 py-3 flex items-center justify-between sticky top-0 z-30 shadow-sm">
        <div className="flex items-center gap-3">
          <button
            onClick={() => setSidebarOpen(true)}
            className="lg:hidden w-9 h-9 rounded-lg flex items-center justify-center hover:bg-gray-100"
          >
            ☰
          </button>
          <div>
            <h1 className="font-bold text-lg text-gray-900 leading-tight">
              Detección de Enfermedades
            </h1>
            <p className="text-xs text-gray-400">
              Monitorea y gestiona las detecciones realizadas en campo
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {/* Notificaciones */}
          <button className="relative w-10 h-10 rounded-full bg-gray-50 border border-gray-200 flex items-center justify-center hover:bg-gray-100 transition">
            🔔
            <span className="absolute -top-1 -right-1 w-5 h-5 bg-green-600 text-white text-[10px] font-bold rounded-full flex items-center justify-center">3</span>
          </button>

          {/* Usuario */}
          <div className="flex items-center gap-2.5 cursor-pointer">
            {user?.photoURL ? (
              <img src={user.photoURL} referrerPolicy="no-referrer" alt="avatar" className="w-9 h-9 rounded-full object-cover border-2 border-green-200" />
            ) : (
              <div className="w-9 h-9 rounded-full bg-green-700 flex items-center justify-center text-white text-sm font-bold">
                {initials}
              </div>
            )}
            <div className="hidden sm:block">
              <p className="text-sm font-semibold text-gray-800 leading-tight">{fullName}</p>
              <p className="text-xs text-gray-400">Técnico de Campo</p>
            </div>
            <span className="text-gray-400 text-xs">▾</span>
          </div>
        </div>
      </header>

      <div className="flex flex-1">

        {/* Overlay móvil */}
        {sidebarOpen && (
          <div className="fixed inset-0 bg-black/40 z-30 lg:hidden" onClick={() => setSidebarOpen(false)} />
        )}

        {/* ── SIDEBAR ── */}
        <aside className={`fixed lg:sticky top-0 left-0 h-screen lg:h-[calc(100vh-65px)] w-60 bg-[#1a3a1a] flex flex-col z-40 transition-transform duration-300
          ${sidebarOpen ? "translate-x-0" : "-translate-x-full"} lg:translate-x-0`}
        >
          {/* Logo */}
          <div className="flex items-center gap-3 px-5 py-5 border-b border-white/10">
            <div className="w-10 h-10 rounded-xl bg-green-600 flex items-center justify-center shrink-0">
              <svg width="22" height="22" viewBox="0 0 80 80" fill="none">
                <ellipse cx="30" cy="40" rx="13" ry="20" fill="white" opacity="0.9" transform="rotate(-15 30 40)" />
                <ellipse cx="50" cy="38" rx="13" ry="20" fill="white" opacity="0.75" transform="rotate(15 50 38)" />
                <line x1="40" y1="60" x2="40" y2="72" stroke="white" strokeWidth="3" strokeLinecap="round" />
              </svg>
            </div>
            <div>
              <p className="text-white font-bold text-sm leading-tight">Sigatoka Negra</p>
              <p className="text-green-300 text-xs">Hacienda San Luis</p>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden ml-auto text-white/50 hover:text-white">✕</button>
          </div>

          {/* Nav */}
          <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto">
            {navItems.map(item => (
              <button
                key={item.key}
                onClick={() => handleNav(item.key)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm transition text-left
                  ${activePage === item.key
                    ? "bg-green-600 text-white font-semibold"
                    : "text-green-100/70 hover:bg-white/10 hover:text-white"
                  }`}
              >
                <span className="text-base shrink-0">{item.icon}</span>
                <span className="leading-snug">{item.label}</span>
              </button>
            ))}
          </nav>

          {/* Usuario + cerrar sesión */}
          <div className="px-3 pb-4 space-y-2 border-t border-white/10 pt-3">
            <div className="flex items-center gap-3 px-3 py-2.5 rounded-xl bg-white/10">
              {user?.photoURL ? (
                <img src={user.photoURL} referrerPolicy="no-referrer" alt="" className="w-8 h-8 rounded-full object-cover shrink-0" />
              ) : (
                <div className="w-8 h-8 rounded-full bg-green-500 flex items-center justify-center text-white text-xs font-bold shrink-0">
                  {initials}
                </div>
              )}
              <div className="min-w-0">
                <p className="text-white text-xs font-semibold truncate">{fullName}</p>
                <p className="text-green-300 text-[11px] truncate">Técnico de Campo</p>
              </div>
              <span className="text-white/40 text-xs ml-auto shrink-0">▾</span>
            </div>
            <button
              onClick={confirmLogout}
              className="w-full flex items-center gap-2 px-3 py-2.5 rounded-xl text-green-100/70 hover:bg-white/10 hover:text-white transition text-sm"
            >
              <span>🚪</span> Cerrar sesión
            </button>
          </div>
        </aside>

        {/* ── CONTENIDO PRINCIPAL ── */}
        <main className="flex-1 p-4 sm:p-6 space-y-5 overflow-auto">

          {/* STATS */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            {[
              { icon: "📋", bg: "bg-green-50",  iconBg: "bg-green-100",  val: totalScans,     label: "Detecciones Totales",    sub: "+15 esta semana",       subColor: "text-green-600" },
              { icon: "🍃", bg: "bg-red-50",    iconBg: "bg-red-100",    val: sigatokaNegra,  label: "Sigatoka Negra",         sub: "53.1% del total",       subColor: "text-red-500"   },
              { icon: "🛡️", bg: "bg-orange-50", iconBg: "bg-orange-100", val: moderadoSevero, label: "Nivel Moderado - Severo", sub: "32.8% del total",       subColor: "text-orange-500"},
              { icon: "📅", bg: "bg-blue-50",   iconBg: "bg-blue-100",   val: estaSemana,     label: "Detecciones esta semana", sub: "+6 resp. semana pasada", subColor: "text-blue-500"  },
            ].map((s, i) => (
              <div key={i} className={`${s.bg} rounded-2xl p-4 border border-white`}>
                <div className="flex items-start gap-3">
                  <div className={`${s.iconBg} w-11 h-11 rounded-xl flex items-center justify-center text-xl shrink-0`}>
                    {s.icon}
                  </div>
                  <div className="min-w-0">
                    <p className="text-2xl font-bold text-gray-900">{s.val}</p>
                    <p className="text-xs text-gray-500 leading-tight mt-0.5">{s.label}</p>
                    <p className={`text-xs font-medium mt-1 ${s.subColor}`}>{s.sub}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* FILA MEDIA — tabla + donut */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">

            {/* Detecciones recientes */}
            <div className="lg:col-span-2 bg-white rounded-2xl border border-gray-100 overflow-hidden">
              <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100">
                <h2 className="font-bold text-gray-800">Detecciones Recientes</h2>
                <button onClick={() => navigate("/scan")} className="text-green-700 text-sm font-medium hover:underline">
                  Ver todas
                </button>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="bg-gray-50 text-gray-500 text-xs">
                      <th className="text-left px-5 py-3 font-medium">Fecha</th>
                      <th className="text-left px-3 py-3 font-medium">Lote</th>
                      <th className="text-left px-3 py-3 font-medium">Resultado</th>
                      <th className="text-left px-3 py-3 font-medium">Severidad</th>
                      <th className="text-center px-3 py-3 font-medium">Estado</th>
                    </tr>
                  </thead>
                  <tbody>
                    {DETECCIONES.map((d, i) => {
                      const sev = severidadConfig[d.severidad] || severidadConfig.Leve;
                      return (
                        <tr
                          key={d.id}
                          className="border-t border-gray-50 hover:bg-gray-50 transition cursor-pointer"
                          onClick={() => navigate(`/result/${d.id}`)}
                        >
                          <td className="px-5 py-3">
                            <div className="flex items-center gap-3">
                              <img src={d.image} alt="" className="w-10 h-10 rounded-xl object-cover shrink-0" />
                              <div>
                                <p className="font-medium text-gray-800 text-xs">{d.fecha}</p>
                                <p className="text-gray-400 text-[11px]">{d.hora}</p>
                              </div>
                            </div>
                          </td>
                          <td className="px-3 py-3">
                            <p className="text-xs font-medium text-gray-800">{d.lote}</p>
                            <p className="text-[11px] text-gray-400">{d.bloque}</p>
                          </td>
                          <td className={`px-3 py-3 text-xs font-semibold ${resultadoColor[d.resultado] || "text-gray-600"}`}>
                            {d.resultado}
                          </td>
                          <td className="px-3 py-3">
                            <span className={`text-xs font-semibold px-2.5 py-1 rounded-full border ${sev.bg} ${sev.text} ${sev.border}`}>
                              {d.severidad}
                            </span>
                          </td>
                          <td className="px-3 py-3 text-center">
                            <span className="text-green-600 text-lg">👁️</span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Donut por severidad */}
            <div className="bg-white rounded-2xl border border-gray-100 p-5">
              <h2 className="font-bold text-gray-800 mb-4">Detecciones por Nivel de Severidad</h2>
              <div className="flex flex-col items-center">
                <DonutChart />
                <div className="space-y-2 w-full mt-4">
                  {[
                    { label: "Leve",     val: 44, pct: "34.4%", color: "bg-green-500"  },
                    { label: "Moderado", val: 42, pct: "32.8%", color: "bg-orange-400" },
                    { label: "Severo",   val: 24, pct: "18.8%", color: "bg-red-500"    },
                    { label: "Sana",     val: 18, pct: "14.1%", color: "bg-green-900"  },
                  ].map((item, i) => (
                    <div key={i} className="flex items-center justify-between text-xs">
                      <div className="flex items-center gap-2">
                        <span className={`w-3 h-3 rounded-sm shrink-0 ${item.color}`} />
                        <span className="text-gray-600">{item.label}</span>
                      </div>
                      <span className="text-gray-800 font-medium">{item.val} ({item.pct})</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* FILA INFERIOR — gráfica + lotes + resumen */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">

            {/* Gráfica evolución */}
            <div className="bg-white rounded-2xl border border-gray-100 p-5">
              <div className="flex items-center justify-between mb-4">
                <h2 className="font-bold text-gray-800">Evolución de Detecciones</h2>
                <span className="text-xs text-gray-500 bg-gray-100 px-3 py-1 rounded-full">Últimos 7 días ▾</span>
              </div>
              <canvas ref={canvasRef} width={480} height={160} className="w-full" />
            </div>

            {/* Lotes + resumen */}
            <div className="flex flex-col gap-4">

              {/* Detecciones por lote */}
              <div className="bg-white rounded-2xl border border-gray-100 p-5 flex-1">
                <div className="flex items-center justify-between mb-3">
                  <h2 className="font-bold text-gray-800 text-sm">Detecciones por Lote</h2>
                  <button onClick={() => navigate("/map")} className="text-green-700 text-xs font-medium hover:underline">
                    Ver mapa
                  </button>
                </div>
                <div className="space-y-2.5">
                  {LOTES.map((lote, i) => (
                    <div key={i} className="flex items-center gap-3 text-xs">
                      <span className="text-gray-600 w-32 shrink-0 truncate">{lote.nombre}</span>
                      <div className="flex-1 h-2 bg-gray-100 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-green-700 rounded-full"
                          style={{ width: `${(lote.cantidad / lote.max) * 100}%` }}
                        />
                      </div>
                      <span className="text-gray-800 font-semibold w-5 text-right shrink-0">{lote.cantidad}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Resumen diagnósticos */}
              <div className="bg-white rounded-2xl border border-gray-100 p-5">
