                    { icon: "🌿", val: 18,  label: "Sanas",          pct: "14.1%", color: "text-green-600"  },
                    { icon: "🍃", val: 68,  label: "Sigatoka Negra", pct: "53.1%", color: "text-red-500"    },
                    { icon: "🛡️", val: 42,  label: "Moderado-Severo",pct: "32.8%", color: "text-orange-500" },
                    { icon: "📋", val: 128, label: "Total Detecciones",pct: "",      color: "text-blue-600"  },
                  ].map((item, i) => (
                    <div key={i} className="text-center">
